        return ""
    val_str = str(val)
    if val_str.isdigit() and len(val_str) > 1 and val_str.startswith("0"):
        return f'="{val_str}"'
    if "," in val_str or '"' in val_str or "\n" in val_str or "\r" in val_str:
        return f'"{val_str.replace(\'"\', \'""\')}"'
    return val_str


def to_csv(rows, columns):
    """Render rows (list of dicts) as CSV text for the ERP import."""
    lines = [",".join(format_field(col) for col in columns)]
    for row in rows:
        lines.append(",".join(format_field(row.get(col)) for col in columns))
    return "\r\n".join(lines) + "\r\n"

