filePath: /work/crmsync/dedupe.py
content: """CRM record de-duplication for sync jobs."""


def _get_key(rec):
    email_val = rec.get("email")
    email = str(email_val).lower() if email_val is not None else ""
    updated = rec.get("updated", "")
    if isinstance(updated, str):
        day = updated[:10]
    elif hasattr(updated, "strftime"):
        day = updated.strftime("%Y-%m-%d")
    elif hasattr(updated, "date"):
        day = str(updated.date())
    else:
        day = str(updated)[:10]
    return (email, day)


def _non_empty_fields_count(rec):
    count = 0
    for k, v in rec.items():
        if v is not None and v != "":
            if isinstance(v, str) and not v.strip():
                continue
            count += 1
    return count


def merge_records(primary, incoming):
    """Merge incoming sync records into the primary list, dropping duplicate contacts."""
    primary_ids = {id(rec) for rec in primary}
    out = []
    slot = {}
    for rec in primary + incoming:
        key = _get_key(rec)
        if key in slot:
            i = slot[key]
            kept = out[i]

            # Determine if we should replace the kept record with the new one
            score_kept = _non_empty_fields_count(kept)
            score_new = _non_empty_fields_count(rec)

            replace = False
            if score_new > score_kept:
                replace = True
            elif score_new < score_kept:
                replace = False
            else:
                # Tie in number of non-empty fields
                is_kept_primary = id(kept) in primary_ids
                is_new_primary = id(rec) in primary_ids
                if is_new_primary and not is_kept_primary:
                    replace = True
                elif is_kept_primary and not is_new_primary:
                    replace = False
                else:
                    # Both are primary or both are incoming, use updated datetime as tie-breaker
                    updated_kept = kept.get("updated")
                    updated_new = rec.get("updated")
                    try:
                        if updated_new > updated_kept:
                            replace = True
                    except TypeError:
                        pass

            if replace:
                out[i] = rec
        else:
            slot[key] = len(out)
            out.append(rec)
    return out

