newString: def merge_records(primary, incoming):
    """Merge incoming sync records into the primary list, dropping duplicate contacts."""
    def get_fill_count(rec):
        count = 0
        for k, v in rec.items():
            if v is not None and v != "":
                count += 1
        return count

    def get_key(rec):
        email = rec.get("email", "").lower()
        updated = rec.get("updated", "")
        day = updated.split("T")[0] if "T" in updated else updated[:10]
        return (email, day)

    def should_replace(old_rec, old_is_primary, new_rec, new_is_primary):
        old_fill = get_fill_count(old_rec)
        new_fill = get_fill_count(new_rec)
        if new_fill > old_fill:
            return True
        elif new_fill < old_fill:
            return False
        else:
            # Tie: prioritize primary-side record
            if old_is_primary and not new_is_primary:
                return False
            if not old_is_primary and new_is_primary:
                return True
            return False  # keep first one encountered

    merged_dict = {}

    for rec in primary:
        key = get_key(rec)
        if key in merged_dict:
            old_rec, old_is_primary = merged_dict[key]
            if should_replace(old_rec, old_is_primary, rec, True):
                merged_dict[key] = (rec, True)
        else:
            merged_dict[key] = (rec, True)

    for rec in incoming:
        key = get_key(rec)
        if key in merged_dict:
            old_rec, old_is_primary = merged_dict[key]
            if should_replace(old_rec, old_is_primary, rec, False):
                merged_dict[key] = (rec, False)
        else:
            merged_dict[key] = (rec, False)

    return [rec for rec, is_primary in merged_dict.values()]

