import ipaddress


def _normalize(name):
    name = name.lower()
    if name.endswith('.'):
        name = name[:-1]
    return name


def _is_ipv4_literal(host):
    if host.count('.') == 3:
        try:
            ipaddress.IPv4Address(host)
            return True
        except ValueError:
            pass
    return False


def is_allowed(host, allowlist):
    """Check an outbound host against the egress allowlist."""
    normalized_host = _normalize(host)

    for entry in allowlist:
        normalized_entry = _normalize(entry)

        if normalized_entry.startswith("*."):
            if _is_ipv4_literal(normalized_host):
                continue

            domain_part = normalized_entry[2:]
            suffix = "." + domain_part
            if normalized_host.endswith(suffix):
                label = normalized_host[:-len(suffix)]
                if label and "." not in label:
                    return True
        else:
            if normalized_host == normalized_entry:
                return True

    return False

