filePath: /work/logsafe/redact.py
content: """Redact sensitive fields from log events."""


def _is_card_number_key(key):
    if not isinstance(key, str):
        return False
    k = key.lower()
    return "card" in k


def _is_fully_masked_key(key):
    if not isinstance(key, str):
        return False
    k = key.lower()
    return any(
        s in k
        for s in (
            "password",
            "token",
            "api_key",
            "apikey",
            "api-key",
            "secret",
            "passwd",
            "ssn",
            "social_security",
            "social-security",
            "socialsecurity",
        )
    )


def _redact_field_val(val, key):
    if _is_card_number_key(key):
        val_str = str(val) if val is not None else ""
        tail = val_str[-4:] if len(val_str) >= 4 else val_str
        return "***" + tail
    elif _is_fully_masked_key(key):
        return "***"
    else:
        return _redact_val(val)


def _redact_val(val):
    if isinstance(val, dict):
        return {
            k: _redact_field_val(v, k)
            for k, v in val.items()
        }
    elif isinstance(val, list):
        return [_redact_val(x) for x in val]
    elif isinstance(val, tuple):
        return tuple(_redact_val(x) for x in val)
    return val


def redact(event):
    """Mask sensitive fields in a log event."""
    if isinstance(event, dict):
        return _redact_val(event)
    return _redact_val(dict(event))

