content: """Append-only per-tenant audit ledger."""


class SequenceGapError(Exception):
    """Raised when an event's seq does not follow the tenant's sequence."""


class SequenceConflictError(Exception):
    """Raised when an event conflicts with one already recorded."""


def append_event(ledger, event):
    """Record an audit event in the tenant's sequence."""
    tenant = event["tenant"]
    seq = event["seq"]
    events = ledger.get(tenant, [])

    for stored in events:
        if stored["seq"] == seq:
            if stored.get("payload_hash") != event.get("payload_hash"):
                raise SequenceConflictError("Conflict for seq %d" % seq)
            return True

    if not events:
        if seq != 1:
            raise SequenceGapError("First event must be seq 1, got %d" % seq)
    else:
        last_seq = events[-1]["seq"]
        if seq <= last_seq:
            raise SequenceGapError("stale seq %d for %s" % (seq, tenant))

        if event.get("type") == "compaction":
            if seq != last_seq + 100:
                raise SequenceGapError("Compaction event sequence must advance by exactly 100, got %d" % seq)
        else:
            if seq != last_seq + 1:
                raise SequenceGapError("Non-compaction event sequence must advance by exactly 1, got %d" % seq)

    if tenant not in ledger:
        ledger[tenant] = []
    ledger[tenant].append(dict(event))
    return True

