from datetime import datetime, timedelta


def _t(s):
    return datetime.fromisoformat(s)


def downtime_minutes(incidents, maintenance):
    """Total SLA downtime in minutes for a billing period."""
    # 1. Parse and merge all overlapping or touching incident windows
    parsed_incidents = []
    for inc in incidents:
        parsed_incidents.append((_t(inc["start"]), _t(inc["end"])))

    parsed_incidents.sort(key=lambda x: x[0])

    merged_incidents = []
    for start, end in parsed_incidents:
        if not merged_incidents:
            merged_incidents.append((start, end))
        else:
            prev_start, prev_end = merged_incidents[-1]
            if start <= prev_end:  # Overlapping or touching
                merged_incidents[-1] = (prev_start, max(prev_end, end))
            else:
                merged_incidents.append((start, end))

    # 2. Ignore any resulting merged outage with a duration less than 60 seconds
    valid_incidents = []
    for start, end in merged_incidents:
        if (end - start).total_seconds() >= 60.0:
            valid_incidents.append((start, end))

    # 3. Filter and parse valid maintenance windows (announced >= 24h prior)
    valid_maintenance = []
    for m in maintenance:
        announced_at = m.get("announced_at")
        if not announced_at:
            continue
        try:
            m_start = _t(m["start"])
            announced = _t(announced_at)
            if (m_start - announced) >= timedelta(hours=24):
                valid_maintenance.append((m_start, _t(m["end"])))
        except Exception:
            continue

    # Merge overlapping or touching maintenance windows to avoid double-subtraction
    valid_maintenance.sort(key=lambda x: x[0])
    merged_maintenance = []
    for start, end in valid_maintenance:
        if not merged_maintenance:
            merged_maintenance.append((start, end))
        else:
            prev_start, prev_end = merged_maintenance[-1]
            if start <= prev_end:
                merged_maintenance[-1] = (prev_start, max(prev_end, end))
            else:
                merged_maintenance.append((start, end))

    # 4. Subtract overlap with merged maintenance windows
    total_seconds = 0.0
    for inc_start, inc_end in valid_incidents:
        span = (inc_end - inc_start).total_seconds()
        for maint_start, maint_end in merged_maintenance:
            lo = max(inc_start, maint_start)
            hi = min(inc_end, maint_end)
            overlap = max((hi - lo).total_seconds(), 0.0)
            span -= overlap
        total_seconds += span

    return total_seconds / 60.0

