newString: def advance(order, target):
    """Move an order to `target`, refusing moves that go backwards."""
    cur = order["state"]
    if not isinstance(cur, str) or not isinstance(target, str):
        raise InvalidTransition(str(cur) + " -> " + str(target))

    cur_lower = cur.lower()
    target_lower = target.lower()

    if cur_lower not in _ORDER or target_lower not in _ORDER:
        raise InvalidTransition(str(cur) + " -> " + str(target))

    # Exception to allow parking a paid order on hold
    if cur_lower == "paid" and target_lower == "on_hold":
        order["state"] = target_lower
        return order

    # Exception to allow releasing hold back to pending
    if cur_lower == "on_hold" and target_lower == "pending":
        order["state"] = target_lower
        return order

    # Block transition if going backwards
    if _ORDER.index(target_lower) <= _ORDER.index(cur_lower):
        raise InvalidTransition(str(cur) + " -> " + str(target))

    # Stop orders landing in impossible statuses
    charged_states = {"paid", "shipped", "returned", "refunded"}
    if cur_lower in charged_states and target_lower == "cancelled":
        raise InvalidTransition(str(cur) + " -> " + str(target))

    if cur_lower == "cancelled" and target_lower == "refunded":
        raise InvalidTransition(str(cur) + " -> " + str(target))

    # Refund is reachable ONLY from returned
    if target_lower == "refunded" and cur_lower != "returned":
        raise InvalidTransition(str(cur) + " -> " + str(target))

    order["state"] = target_lower
    return order

