newString: def merge_tags(sources):
    """Merge tag lists from every source into one combined list."""
    if not sources:
        return []

    tombstone_lowers_per_source = []
    for tags in sources:
        lowers = set()
        for tag in tags:
            if tag.startswith("-"):
                lowers.add(tag[1:].lower())
        tombstone_lowers_per_source.append(lowers)

    out = []
    seen_lowers = set()

    for i, tags in enumerate(sources):
        for tag in tags:
            if tag.startswith("-"):
                continue

            tag_lower = tag.lower()

            suppressed = False
            for k in range(i):
                if tag_lower in tombstone_lowers_per_source[k]:
                    suppressed = True
                    break

            if suppressed:
                continue

            if tag_lower not in seen_lowers:
                seen_lowers.add(tag_lower)
                out.append(tag)

    return out

