newString: def merge_tags(sources):
    """Merge tag lists from every source into one combined list."""
    tombstones_before_level = []
    current_tombstones = set()
    for tags in sources:
        tombstones_before_level.append(set(current_tombstones))
        for tag in tags:
            if tag.startswith('-'):
                current_tombstones.add(tag[1:].lower())

    merged_list = []
    kept_lowercase = set()

    for i, tags in enumerate(sources):
        active_tombstones = tombstones_before_level[i]
        for tag in tags:
            if tag.startswith('-'):
                continue

            tag_lower = tag.lower()
            if tag_lower in kept_lowercase:
                continue

            if tag_lower in active_tombstones:
                continue

            kept_lowercase.add(tag_lower)
            merged_list.append(tag)

    return merged_list
