newString: """Config quantity parsing for the provisioning pipeline."""

_UNITS = {"K": 1000, "M": 1000 ** 2, "G": 1000 ** 3, "T": 1000 ** 4}


def parse_quantity(value, kind):
    """Convert a config quantity like '512M' into bytes for the given
    resource kind ("memory" or "disk")."""
    s = str(value).strip()
    if not s:
        raise ValueError("empty quantity")

    if kind == "memory":
        units = {
            "K": 1024,
            "M": 1024 ** 2,
            "G": 1024 ** 3,
            "T": 1024 ** 4,
        }
        if s[-1].isalpha():
            suffix = s[-1].upper()
            if suffix not in units:
                raise ValueError("invalid unit suffix for memory: " + s[-1])
            return int(s[:-1]) * units[suffix]
        return int(s) * (1024 ** 2)

    elif kind == "disk":
        units = {
            "M": 1000 ** 2,
            "G": 1000 ** 3,
            "T": 1000 ** 4,
        }
        if s[-1].isalpha():
            suffix = s[-1].upper()
            if suffix not in units:
                raise ValueError("invalid unit suffix for disk: " + s[-1])
            return int(s[:-1]) * units[suffix]
        return int(s) * (1000 ** 3)

    else:
        raise ValueError("invalid resource kind: " + str(kind))

